import sys

def count_set_bits(num):
    count = 0
    while num != 0:
        count += (num & 1)
        num >>= 1
    return count

def check_pattern(a, b, c, maxm):
    combined = (maxm - 1) & (b | (b << 1) | (b >> 1) | a | c)
    return combined == maxm - 1

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    if n < m:
        n, m = m, n
    maxm = 1 << m

    # Initialize dp array with size (n+1) x maxm x maxm filled with 100
    dp = [[[100 for _ in range(maxm)] for _ in range(maxm)] for _ in range(n + 1)]
    s = [0] * maxm

    for i in range(maxm):
        s[i] = count_set_bits(i)
        dp[0][0][i] = 0

    for rowIdx in range(1, n + 1):
        for prevMask in range(maxm):
            for currMask in range(maxm):
                for nextMask in range(maxm):
                    if dp[rowIdx - 1][prevMask][nextMask] != 100 and check_pattern(prevMask, nextMask, currMask, maxm):
                        dp[rowIdx][currMask][nextMask] = min(dp[rowIdx][currMask][nextMask], dp[rowIdx - 1][prevMask][nextMask] + s[nextMask])

    minRes = float('inf')
    for i in range(maxm):
        minRes = min(dp[n][i][0], minRes)

    print(n * m - minRes)

